import React, { useState, useEffect } from 'react';
import gameService from '../../services/gameService';
import './GamesPreview.css';

const GamesPreview = () => {
  const [games, setGames] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    // Функция для загрузки игр
    const fetchGames = async () => {
      try {
        const gamesData = await gameService.getUserGames();
        setGames(gamesData);
      } catch (error) {
        console.error('Ошибка при загрузке игр:', error);
        setError('Не удалось загрузить игры');
      } finally {
        setLoading(false);
      }
    };

    fetchGames();
  }, []);

  const handlePlayGame = (gameId) => {
    // Переход к игре
    window.location.href = `/game/${gameId}`;
  };

  const handleDeleteGame = async (gameId) => {
    if (window.confirm('Вы уверены, что хотите удалить эту игру?')) {
      try {
        await gameService.deleteGame(gameId);
        setGames(games.filter(game => game.id !== gameId));
      } catch (error) {
        console.error('Ошибка при удалении игры:', error);
        alert('Не удалось удалить игру');
      }
    }
  };

  if (loading) {
    return (
      <div className="loading-container">
        <div className="loading-spinner"></div>
        <p>Загрузка игр...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="error-container">
        <p className="error-message">{error}</p>
      </div>
    );
  }

  if (games.length === 0) {
    return (
      <div className="empty-state">
        <div className="empty-state-content">
          <h3>У вас пока нет игр</h3>
          <p>Перейдите в "Конструктор игр", чтобы создать свою первую игру!</p>
        </div>
      </div>
    );
  }

  return (
    <div className="games-preview-container">
      <div className="games-grid">
        {games.map((game) => (
          <div key={game.id} className="game-card">
            <div className="game-card-header">
              <h3 className="game-title">{game.name}</h3>
              <span className="game-type">{game.type || 'wheel'}</span>
            </div>
            
            <div className="game-card-body">
              {game.description && (
                <p className="game-description">{game.description}</p>
              )}
              
              <div className="game-stats">
                <span className="game-stat">
                  <strong>Создано:</strong> {new Date(game.created_at).toLocaleDateString('ru-RU')}
                </span>
              </div>
            </div>
            
            <div className="game-card-actions">
              <button 
                className="btn btn-primary"
                onClick={() => handlePlayGame(game.id)}
              >
                Играть
              </button>
              <button 
                className="btn btn-danger"
                onClick={() => handleDeleteGame(game.id)}
              >
                Удалить
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default GamesPreview;
